    check($status===200 && str_contains($html,'พบ 0 คน'),'Survey group filter excludes other centers');
    $pdo->exec("INSERT INTO students(id,student_code,firstname,lastname) VALUES(2,'TEST002','ผู้เรียนอื่น','ทดสอบ'); INSERT INTO enrollments(id,student_id,academic_term_id,education_level,learning_center_id,teacher_id) VALUES(2,2,1,'upper_secondary',1,2)");
    [$status]=$request('/surveys/2?term_id=1',null,'teacher');check($status===403,'Teacher cannot read another assignment survey');
