    [$status]=$request('/followups/'.$task['id'].'/update-status',['_csrf_token'=>'test-token','status'=>'completed'],'super_admin');
    check($status===302 && $pdo->query('SELECT completed_at FROM followups WHERE id='.$task['id'])->fetchColumn()!==null,'Complete followup records completion timestamp');
    [$status]=$request('/followups/'.$task['id'].'/update-status',['_csrf_token'=>'test-token','status'=>'pending'],'super_admin');
    check($status===302 && $pdo->query('SELECT completed_at FROM followups WHERE id='.$task['id'])->fetchColumn()===null,'Reopening followup clears stale completion timestamp');
    $historical=$pdo->query('SELECT q.*,q.id question_id FROM assessment_questions q WHERE id='.$duplicate)->fetch();
    $historical['answer_value']='บ้านเช่า';
    check(AssessmentQuestion::answersForActive($pdo,[$historical])[1]==='บ้านเช่า','Retired equivalent question answers seed active fields by full definition');
    // Local administrator credential management, through real HTTP routes.
    $userModelFile=APP_ROOT.'/app/models/User.php'; require_once $userModelFile;
    $pdo->prepare("INSERT INTO users(id,username,password,firstname,lastname,role,organization_id) VALUES(3,'admin-fixture',?,'ผู้ดูแล','ทดสอบ','admin',1),(4,'root-fixture',?,'ผู้ดูแลสูงสุด','ทดสอบ','super_admin',1)")->execute([password_hash('old-admin-password',PASSWORD_DEFAULT),password_hash('root-old-password',PASSWORD_DEFAULT)]);
    [$status,,$html]=$request('/users/3/edit',null,'admin');
