    [$status,$headers]=$request('/users/3/edit',$credentials,'admin');
    $updated=(new User())->findById(3);
    check($status===302 && !str_contains($headers,'/edit') && $updated['username']==='admin-renamed','Admin username changed');
    check(password_verify('new-admin-password',$updated['password']) && !password_verify('old-admin-password',$updated['password']),'Password securely replaced');
    check($updated['role']==='admin' && $updated['firstname']==='ผู้ดูแล','Credential update preserves role and profile');
    $savedHash=$updated['password']; $onlyName=['_csrf_token'=>'test-token','username'=>'admin-name-only','new_password'=>'','password_confirmation'=>''];
    [$status]=$request('/users/3/edit',$onlyName,'admin');
    check($status===302 && (new User())->findById(3)['password']===$savedHash,'Username-only change keeps password');
    $duplicateName=$credentials;$duplicateName['username']='root-fixture';
    [$status,$headers]=$request('/users/3/edit',$duplicateName,'admin');
    check($status===302 && str_contains($headers,'/edit') && (new User())->findById(3)['username']==='admin-name-only','Duplicate username rejected atomically');
    $mismatch=$credentials; $mismatch['password_confirmation']='different-password';
    [$status]=$request('/users/3/edit',$mismatch,'admin');
    check($status===302 && (new User())->findById(3)['password']===$savedHash,'Mismatched confirmation rejected');
    $short=$credentials;$short['new_password']='short';$short['password_confirmation']='short';
    [$status]=$request('/users/3/edit',$short,'admin');
    check($status===302 && (new User())->findById(3)['password']===$savedHash,'Short password rejected');
    $noCsrf=$credentials;unset($noCsrf['_csrf_token']);
    [$status]=$request('/users/3/edit',$noCsrf,'admin');check($status===403,'Credential write requires CSRF');
    [$status]=$request('/users/4/edit',$credentials,'admin');check($status===403,'Protected-account write rejected');
    $pdo->exec("INSERT INTO sdl_links(entity,source_key,local_id,snapshot,synced_at) VALUES('teacher','fixture-source',2,'{}',NOW())");
    [$status]=$request('/users/2/edit',$credentials,'admin');
    check($status===302 && (new User())->findById(2)['username']==='other-fixture','Source teacher credentials cannot be overwritten locally');
    foreach(['AcademicTerm','Student'] as $model) require_once APP_ROOT.'/app/models/'.$model.'.php';
    require_once APP_ROOT.'/app/helpers/auth.php';
    foreach(['SdlApiClient','SdlSyncService','AuthService'] as $service) require_once APP_ROOT.'/app/services/'.$service.'.php';
    [$status]=$request('/users/4/edit',['_csrf_token'=>'test-token','username'=>'root-updated','prefix'=>'นาย','firstname'=>'ผู้ดูแลแก้ไข','lastname'=>'ทดสอบ','email'=>'root-update@example.test','phone'=>'0891234567','new_password'=>'','password_confirmation'=>''], 'super_admin');
    $rootAccount=(new User())->findById(4);
    check($status===302 && $rootAccount['username']==='root-updated' && $rootAccount['firstname']==='ผู้ดูแลแก้ไข' && $rootAccount['role']==='super_admin','Superadmin profile and credentials editable without role changes');
    // Selected-term recording must not silently use the session's current term.
    $pdo->exec("INSERT INTO academic_terms(id,term_name,academic_year,term_no,is_current) VALUES(2,'2/2569',2569,2,0); INSERT INTO enrollments(id,student_id,academic_term_id,education_level,learning_center_id,teacher_id) VALUES(3,1,2,'upper_secondary',1,2)");
    [$status]=$request('/visits/create/1?term_id=2',null,'teacher');
