    check($status===302 && (int)$pdo->query('SELECT enrollment_id FROM home_visits ORDER BY id DESC LIMIT 1')->fetchColumn()===3,'District admin records against selected term instead of current session term');
    session_start(); $auth=new AuthService();
    check($auth->login('admin-name-only','new-admin-password')['success'],'Updated admin credentials log in successfully');
    check(!$auth->login('admin-fixture','old-admin-password')['success'],'Old username cannot log in');
    check(!$auth->login('admin-name-only','old-admin-password')['success'],'Old password cannot log in');
    session_destroy();
    echo "Passed $checks checks (isolated database and temporary PDF; no live data changes).\n";
} finally {
    if(is_resource($process)){proc_terminate($process);proc_close($process);}
    foreach($createdFiles as $file)@unlink(APP_ROOT.'/public/uploads/visits/'.basename($file));
    (new ReflectionProperty(Database::class,'instance'))->setValue(null,null);$pdo=null;
    $server->exec("DROP DATABASE IF EXISTS `$name`");
    foreach(glob($temp.'/*')?:[] as $file)unlink($file);rmdir($temp);
}
